1	//! # p64-bridge — lance-graph → p64 palette wiring
2	//!
3	//! Maps lance-graph types to p64-compatible palette operations.
4	//! **No p64 dependency** — provides compatible constants and mapping functions.
5	//! The consumer imports both `p64` and `p64-bridge`, connecting them at the call site.
6	//!
7	//! ## Architecture
8	//!
9	//! ```text
10	//! lance-graph                    p64 (ndarray)
11	//! ──────────                     ─────────────
12	//! CausalEdge64 ──→ p64-bridge ──→ palette row/col addressing
13	//! ThinkingStyle ──→ p64-bridge ──→ layer_mask + combine + contra
14	//! HdrSemiring   ──→ p64-bridge ──→ combine_mode + contra_mode
15	//! ```
16	
17	use std::sync::LazyLock;
18	
19	use causal_edge::edge::CausalEdge64;
20	
21	// ============================================================================
22	// CausalEdge64 → Palette64 addressing
23	// ============================================================================
24	
25	/// Map a CausalEdge64 to a 64×64 palette block address.
26	///
27	/// S[0:7] → block row (S/4), O[16:23] → block col (O/4).
28	/// The 256 palette indices map to 64 blocks of 4.
29	#[inline]
30	pub fn edge_to_block(edge: &CausalEdge64) -> (usize, usize) {
31	    let row = edge.s_idx() as usize / 4;
32	    let col = edge.o_idx() as usize / 4;
33	    (row.min(63), col.min(63))
34	}
35	
36	/// Extract NARS frequency + confidence as f32 pair.
37	#[inline]
38	pub fn edge_nars_f32(edge: &CausalEdge64) -> (f32, f32) {
39	    (
40	        edge.frequency_u8() as f32 / 255.0,
41	        edge.confidence_u8() as f32 / 255.0,
42	    )
43	}
44	
45	/// Map CausalEdge64's causal mask + inference type to an 8-bit predicate layer mask.
46	///
47	/// ```text
48	/// Pearl causal mask:
49	///   bit 0 (direct)      → Layer 0 CAUSES
50	///   bit 1 (enabling)    → Layer 1 ENABLES
51	///   bit 2 (confounding) → Layer 3 CONTRADICTS
52	///
53	/// Inference type:
54	///   0 Deduction  → Layer 0 CAUSES
55	///   1 Induction  → Layer 2 SUPPORTS
56	///   2 Abduction  → Layer 5 ABSTRACTS
57	///   3 Revision   → Layer 4 REFINES
58	///   4 Synthesis  → Layer 7 BECOMES
59	/// ```
60	#[inline]
61	pub fn edge_to_layer_mask(edge: &CausalEdge64) -> u8 {
62	    let causal = edge.causal_mask() as u8;
63	    let infer = edge.inference() as u8;
64	
65	    let mut mask = 0u8;
66	
67	    // Pearl's causal mask → predicate layers
68	    if causal & 1 != 0 {
69	        mask |= 1 << CAUSES;
70	    }
71	    if causal & 2 != 0 {
72	        mask |= 1 << ENABLES;
73	    }
74	    if causal & 4 != 0 {
75	        mask |= 1 << CONTRADICTS;
76	    }
77	
78	    // Inference type → predicate layer
79	    mask |= match infer {
80	        0 => 1 << CAUSES,
81	        1 => 1 << SUPPORTS,
82	        2 => 1 << ABSTRACTS,
83	        3 => 1 << REFINES,
84	        4 => 1 << BECOMES,
85	        _ => 1 << GROUNDS,
86	    };
87	
88	    mask
89	}
90	
91	/// Build a 64×64 bitmask from a batch of CausalEdge64 values.
92	/// Returns `[u64; 64]` directly usable as `Palette64::rows`.
93	pub fn edges_to_palette_rows(edges: &[CausalEdge64]) -> [u64; 64] {
94	    let mut rows = [0u64; 64];
95	    for edge in edges {
96	        let (row, col) = edge_to_block(edge);
97	        rows[row] |= 1u64 << col;
98	    }
99	    rows
100	}
101	
102	/// Build 8 layered palette row arrays from edges (for Palette3D).
103	/// Each edge is routed to the appropriate predicate layers based on
104	/// its causal mask and inference type.
105	pub fn edges_to_layered_rows(edges: &[CausalEdge64]) -> [[u64; 64]; 8] {
106	    let mut layers = [[0u64; 64]; 8];
107	    for edge in edges {
108	        let (row, col) = edge_to_block(edge);
109	        let layer_mask = edge_to_layer_mask(edge);
110	        for (z, layer) in layers.iter_mut().enumerate() {
111	            if layer_mask & (1 << z) != 0 {
112	                layer[row] |= 1u64 << col;
113	            }
114	        }
115	    }
116	    layers
117	}
