272	/// Get style params by name. O(n) scan but n=12, so ~12 comparisons max.
273	#[inline]
274	pub fn style_by_name(name: &str) -> &'static StyleParams {
275	    let lower = name.to_lowercase();
276	    STYLES
277	        .iter()
278	        .find(|s| s.name == lower.as_str())
279	        .unwrap_or(&STYLES[0])
280	}
