288	// ============================================================================
289	// Semiring → combine/contra mapping
290	// ============================================================================
291	
292	/// Map a semiring name to (combine_mode, contra_mode) ordinals.
293	///
294	/// ```text
295	/// BOOLEAN          → (Intersection, Suppress)  — strict reachability
296	/// HAMMING_MIN      → (Weighted, Tension)        — shortest path with awareness
297	/// SIMILARITY_MAX   → (Majority, Suppress)       — consensus matching
298	/// XOR_BUNDLE       → (Union, Invert)            — superposition + divergent
299	/// TRUTH_PROPAGATING→ (Weighted, Tension)         — NARS revision chain
300	/// ```
301	pub fn semiring_to_modes(semiring_name: &str) -> (u8, u8) {
302	    match semiring_name {
303	        "BOOLEAN" => (combine::INTERSECTION, contra::SUPPRESS),
304	        "HAMMING_MIN" => (combine::WEIGHTED, contra::TENSION),
305	        "SIMILARITY_MAX" => (combine::MAJORITY, contra::SUPPRESS),
306	        "XOR_BUNDLE" => (combine::UNION, contra::INVERT),
307	        "TRUTH_PROPAGATING" => (combine::WEIGHTED, contra::TENSION),
308	        _ => (combine::MAJORITY, contra::SUPPRESS),
309	    }
310	}
