312	// ============================================================================
313	// CognitiveShader: 8 planes bundled — topology × metric × algebra
314	// ============================================================================
315	
316	/// CognitiveShader: binds p64 topology with bgz17 O(1) distance.
317	///
318	/// ```text
319	/// Mask (p64):     [u64; 64]       WHICH pairs interact (topology)
320	/// Distance (bgz17): [u16; k×k]   HOW FAR apart (metric, O(1) lookup)
321	/// Compose (bgz17):  [u8; k×k]    WHAT path composition means (algebra, O(1))
322	/// ```
323	///
324	/// No POPCNT. No Hamming. Distance is PRECOMPUTED in the codebook.
325	/// The mask gates access. The table provides the answer. O(1).
326	pub mod cognitive_shader {
327	    // DistanceMatrix and Palette retained for the upcoming AriGraph→palette→shader
328	    // convergence highway wiring (TD-P64-SHADER-1).
329	    #[allow(unused_imports)]
330	    use bgz17::distance_matrix::DistanceMatrix;
331	    #[allow(unused_imports)]
332	    use bgz17::palette::Palette;
333	    use bgz17::palette_semiring::PaletteSemiring;
334	
335	    /// 8 planes × 64 rows = 512 u64 = topology mask.
336	    /// Each plane corresponds to a predicate layer (CAUSES..BECOMES).
337	    /// Each bit at `planes[z][row] & (1 << col)` means:
338	    ///   "archetype block `row` relates to block `col` via predicate `z`."
339	    ///
340	    /// Distance between any two archetype indices = `semiring.distance(a, b)`.
341	    /// Path composition = `semiring.compose(a, b)`.
342	    /// Both O(1). The mask just says WHERE to look.
343	    pub struct CognitiveShader<'a> {
344	        /// 8 predicate planes (topology).
345	        pub planes: [[u64; 64]; 8],
346	        /// bgz17 semiring: distance + compose + identity.
347	        pub semiring: &'a PaletteSemiring,
348	        /// Palette size (typically 256).
349	        pub k: usize,
350	    }
351	
352	    /// Result of a cascade query.
353	    #[derive(Debug, Clone)]
354	    pub struct CascadeHit {
355	        /// Target archetype index (0..255).
356	        pub target: u8,
357	        /// Precomputed distance from query to target.
358	        pub distance: u16,
359	        /// Which predicate layers connect them (bitmask).
360	        pub predicates: u8,
361	    }
362	
363	    impl<'a> CognitiveShader<'a> {
364	        /// Construct from layered rows (output of `edges_to_layered_rows`) + bgz17 semiring.
365	        pub fn new(planes: [[u64; 64]; 8], semiring: &'a PaletteSemiring) -> Self {
366	            Self {
367	                planes,
368	                semiring,
369	                k: semiring.k,
370	            }
371	        }
372	
373	        /// HHTL Cascade: find all targets within `radius` of `query`.
374	        ///
375	        /// ```text
376	        /// HEEL: which predicate planes are active? (layer_mask gates Z)
377	        /// HIP:  scan mask row for active bits     (topology gates X-Y)
378	        /// TWIG: expand block → 4 archetype indices (4×4 refinement)
379	        /// LEAF: semiring.distance(query, target)   (O(1) metric lookup)
380	        /// ```
381	        ///
382	        /// Returns hits sorted by distance ascending.
383	        pub fn cascade(&self, query: u8, radius: u16, layer_mask: u8) -> Vec<CascadeHit> {
384	            let block_row = query as usize / 4;
385	            if block_row >= 64 {
386	                return Vec::new();
387	            }
388	
389	            // Collect which block-columns are active across selected layers
390	            let mut active_cols = 0u64;
391	            let mut per_col_predicates = [0u8; 64];
392	
393	            for z in 0..8 {
394	                if layer_mask & (1 << z) == 0 {
395	                    continue;
396	                }
397	                let row_mask = self.planes[z][block_row];
398	                let mut bits = row_mask;
399	                while bits != 0 {
400	                    let col = bits.trailing_zeros() as usize;
401	                    bits &= bits - 1;
402	                    active_cols |= 1u64 << col;
403	                    per_col_predicates[col] |= 1 << z;
404	                }
405	            }
406	
407	            // Expand active block-columns to archetype indices, lookup distance
408	            let mut hits = Vec::new();
409	            let mut bits = active_cols;
410	            while bits != 0 {
411	                let block_col = bits.trailing_zeros() as usize;
412	                bits &= bits - 1;
413	
414	                // 4 archetype indices per block
415	                for sub in 0..4 {
416	                    let target = (block_col * 4 + sub) as u8;
417	                    if (target as usize) >= self.k {
418	                        continue;
419	                    }
420	                    let dist = self.semiring.distance(query, target);
421	                    if dist <= radius {
422	                        hits.push(CascadeHit {
423	                            target,
424	                            distance: dist,
425	                            predicates: per_col_predicates[block_col],
426	                        });
427	                    }
428	                }
429	            }
430	
431	            hits.sort_by_key(|h| h.distance);
432	            hits
433	        }
434	
435	        /// Transitive deduction: A→B→C via compose.
436	        ///
437	        /// Given query A, find all B where A→B exists (CAUSES layer),
438	        /// then for each B, compose(A,B) gives the intermediate,
439	        /// and scan for all C where B→C exists (ENABLES layer).
440	        /// Distance of the composed path = distance(A, compose(A,B)) + distance(compose(A,B), C).
441	        pub fn deduce_path(
442	            &self,
443	            query: u8,
444	            cause_layer: usize,
445	            effect_layer: usize,
446	            max_hops: usize,
447	        ) -> Vec<(u8, u16, Vec<u8>)> {
448	            let mut results = Vec::new();
449	            let mut visited = [false; 256];
450	            visited[query as usize] = true;
451	
452	            let mut frontier = vec![(query, 0u16, vec![query])];
453	
454	            for _hop in 0..max_hops {
455	                let mut next_frontier = Vec::new();
456	
457	                for (current, cumulative_dist, path) in &frontier {
458	                    let block_row = *current as usize / 4;
459	                    if block_row >= 64 {
460	                        continue;
461	                    }
462	
463	                    // Which targets does `current` connect to in the specified layer?
464	                    let layer = if _hop == 0 { cause_layer } else { effect_layer };
465	                    let mask = self.planes[layer.min(7)][block_row];
466	                    let mut bits = mask;
467	
468	                    while bits != 0 {
469	                        let block_col = bits.trailing_zeros() as usize;
470	                        bits &= bits - 1;
471	
472	                        for sub in 0..4 {
473	                            let target = (block_col * 4 + sub) as u8;
474	                            if (target as usize) >= self.k || visited[target as usize] {
475	                                continue;
476	                            }
477	
478	                            // Compose: what does the path through current→target produce?
479	                            let composed = self.semiring.compose(*current, target);
480	                            let step_dist = self.semiring.distance(*current, target);
481	                            let total = cumulative_dist + step_dist;
482	
483	                            visited[target as usize] = true;
484	                            let mut new_path = path.clone();
485	                            new_path.push(target);
486	                            results.push((composed, total, new_path.clone()));
487	                            next_frontier.push((target, total, new_path));
488	                        }
489	                    }
490	                }
491	
492	                if next_frontier.is_empty() {
493	                    break;
494	                }
495	                frontier = next_frontier;
496	            }
497	
498	            results.sort_by_key(|(_, dist, _)| *dist);
499	            results
500	        }
501	
502	        /// Density per layer.
503	        pub fn layer_densities(&self) -> [f32; 8] {
504	            let mut d = [0.0f32; 8];
505	            for (z, slot) in d.iter_mut().enumerate() {
506	                let bits: u32 = self.planes[z].iter().map(|r| r.count_ones()).sum();
507	                *slot = bits as f32 / 4096.0;
508	            }
509	            d
510	        }
511	
512	        /// Memory footprint.
513	        pub fn topology_bytes(&self) -> usize {
514	            8 * 64 * 8 // 8 planes × 64 rows × 8 bytes per u64
515	        }
516	
517	        pub fn metric_bytes(&self) -> usize {
518	            self.semiring.byte_size()
519	        }
520	
521	        pub fn total_bytes(&self) -> usize {
522	            self.topology_bytes() + self.metric_bytes()
523	        }
524	    }
525	}
