538	    #[test]
539	    fn edge_to_palette_addressing() {
540	        let edge = CausalEdge64::pack(
541	            10,                            // S
542	            5,                             // P
543	            20,                            // O
544	            200,                           // frequency
545	            150,                           // confidence
546	            CausalMask::SO,                // causal: S+O active (association)
547	            0,                             // direction
548	            InferenceType::Deduction,      // inference
549	            PlasticityState::from_bits(0), // plasticity
550	            0,                             // temporal
551	        );
552	
553	        let (row, col) = edge_to_block(&edge);
554	        assert_eq!(row, 2); // 10/4
555	        assert_eq!(col, 5); // 20/4
556	
557	        let (f, c) = edge_nars_f32(&edge);
558	        assert!((f - 200.0 / 255.0).abs() < 0.01);
559	        assert!((c - 150.0 / 255.0).abs() < 0.01);
560	
561	        let mask = edge_to_layer_mask(&edge);
562	        assert!(mask & (1 << CAUSES) != 0, "Deduction → CAUSES");
563	
564	        eprintln!("Edge: S=10→row={row}, O=20→col={col}, f={f:.3}, c={c:.3}, layers={mask:08b}");
565	    }
