567	    #[test]
568	    fn batch_edges_to_rows() {
569	        use causal_edge::edge::InferenceType;
570	        let infer_types = [
571	            InferenceType::Deduction,
572	            InferenceType::Induction,
573	            InferenceType::Abduction,
574	            InferenceType::Revision,
575	            InferenceType::Synthesis,
576	        ];
577	
578	        let edges: Vec<CausalEdge64> = (0..50)
579	            .map(|i| {
580	                CausalEdge64::pack(
581	                    ((i * 7) % 256) as u8,
582	                    0,
583	                    ((i * 13 + 3) % 256) as u8,
584	                    128,
585	                    128,
586	                    CausalMask::from_bits((i % 7) as u8),
587	                    0,
588	                    infer_types[i % 5],
589	                    PlasticityState::from_bits(0),
590	                    0,
591	                )
592	            })
593	            .collect();
594	
595	        let rows = edges_to_palette_rows(&edges);
596	        let nnz: u32 = rows.iter().map(|r| r.count_ones()).sum();
597	        eprintln!(
598	            "50 edges → {} non-zero palette bits ({:.1}% density)",
599	            nnz,
600	            nnz as f64 / 4096.0 * 100.0
601	        );
602	        assert!(nnz > 0);
603	
604	        let layers = edges_to_layered_rows(&edges);
605	        for z in 0..8 {
606	            let bits: u32 = layers[z].iter().map(|r| r.count_ones()).sum();
607	            if bits > 0 {
608	                eprintln!(
609	                    "  Layer {z} ({:12}): {} bits",
610	                    [
611	                        "CAUSES",
612	                        "ENABLES",
613	                        "SUPPORTS",
614	                        "CONTRADICTS",
615	                        "REFINES",
616	                        "ABSTRACTS",
617	                        "GROUNDS",
618	                        "BECOMES"
619	                    ][z],
620	                    bits
621	                );
