655	    fn cognitive_shader_cascade() {
656	        use super::cognitive_shader::CognitiveShader;
657	        use bgz17::base17::Base17;
658	        use bgz17::palette::Palette;
659	        use bgz17::palette_semiring::PaletteSemiring;
660	
661	        // Build a small palette: 16 entries with distinct Base17 patterns
662	        let entries: Vec<Base17> = (0..16)
663	            .map(|i| {
664	                let mut dims = [0i16; 17];
665	                dims[0] = (i * 100) as i16; // spread on dim 0
666	                dims[1] = ((i * 37) % 200) as i16;
667	                Base17 { dims }
668	            })
669	            .collect();
670	        let palette = Palette { entries };
671	        let semiring = PaletteSemiring::build(&palette);
672	
673	        // Build layered mask: CAUSES connects neighbors, ENABLES connects every other
674	        let mut planes = [[0u64; 64]; 8];
675	        for i in 0..4 {
676	            // 16 entries / 4 = 4 blocks
677	            // CAUSES: each block connects to next block
678	            if i + 1 < 4 {
679	                planes[CAUSES][i] |= 1u64 << (i + 1);
680	            }
681	            // ENABLES: each block connects to block+2
682	            if i + 2 < 4 {
683	                planes[ENABLES][i] |= 1u64 << (i + 2);
684	            }
685	            // SUPPORTS: self-connection
686	            planes[SUPPORTS][i] |= 1u64 << i;
687	        }
688	
689	        let b = CognitiveShader::new(planes, &semiring);
690	
691	        // Cascade from entry 0, radius = 5000 (wide), all layers
692	        let hits = b.cascade(0, 5000, 0xFF);
693	
694	        eprintln!("\n=== CognitiveShader Cascade ===");
695	        eprintln!("Query: archetype 0, radius=5000, all layers");
696	        eprintln!("Hits: {}", hits.len());
697	        for hit in &hits {
