700	                hit.target, hit.distance, hit.predicates
701	            );
702	        }
703	
704	        assert!(!hits.is_empty(), "Should find at least one hit");
705	        // All distances should be from bgz17 lookup, not POPCNT
706	        for hit in &hits {
707	            let expected_dist = semiring.distance(0, hit.target);
708	            assert_eq!(
709	                hit.distance, expected_dist,
710	                "Distance should match bgz17 O(1) lookup for target {}",
711	                hit.target
712	            );
713	        }
714	
715	        // Memory footprint
716	        eprintln!("Topology: {} bytes", b.topology_bytes());
717	        eprintln!("Metric:   {} bytes", b.metric_bytes());
718	        eprintln!("Total:    {} bytes", b.total_bytes());
719	        eprintln!("Densities: {:?}", b.layer_densities());
720	    }
