70	/// The genius driver: CognitiveShader in the driving seat, BindSpace and
71	/// the bgz17 semiring in the back, thinking-engine optional.
72	pub struct ShaderDriver {
73	    pub(crate) bindspace: Arc<BindSpace>,
74	    pub(crate) semiring: Arc<PaletteSemiring>,
75	    /// 8 predicate planes × 64 rows × u64 columns = 4 KB topology.
76	    /// Boxed to keep the bulk off ShaderDriver's stack frame, and held
77	    /// under an RwLock so the convergence highway (TD-INT-14) can swap
78	    /// in fresh planes when AriGraph commits new SPO knowledge.
79	    pub(crate) planes: RwLock<Box<[[u64; 64]; 8]>>,
