136	    /// Attach precomputed NARS truth tables (TD-INT-10).
137	    ///
138	    /// Builder-style mutation: takes ownership, returns Self. Pass
139	    /// `Arc::new(NarsTables::build(c_levels))` (or share an existing
140	    /// `Arc`) to wire Pearl 2³ + Truth lookups into the cascade.
141	    pub fn with_nars_tables(mut self, tables: Arc<NarsTables>) -> Self {
142	        self.nars_tables = Some(tables);
143	        self
144	    }
