152	    /// Return a read reference to the `MailboxSoA<1024>` registered under
153	    /// `id`, or `None` if no mailbox with that id has been inserted via
154	    /// the builder's `with_mailbox` method.
155	    ///
156	    /// The singleton `Arc<BindSpace>` is unchanged by this accessor.
157	    /// This is the transitional per-mailbox routing read surface (slice A2).
158	    #[inline]
159	    pub fn mailbox(&self, id: MailboxId) -> Option<&MailboxSoA<1024>> {
160	        self.mailboxes.get(&id)
161	    }
162	
163	    /// Borrow the underlying BindSpace (read-only).
164	    #[inline]
165	    pub fn bindspace(&self) -> &BindSpace {
166	        &self.bindspace
167	    }
168	
169	    /// Snapshot the topology planes (8 × 64 u64).
170	    ///
171	    /// Returns a fresh copy because the planes are kept under an `RwLock`
172	    /// (TD-INT-14: convergence highway lets the planner swap in new
173	    /// AriGraph-derived planes at runtime). Callers that just want a
174	    /// stable view of the current topology pay a 4 KB copy.
175	    #[inline]
176	    pub fn planes(&self) -> [[u64; 64]; 8] {
177	        **self.planes.read().expect("planes RwLock poisoned")
178	    }
179	
180	    /// Replace the topology planes at runtime.
181	    ///
182	    /// This is the convergence highway terminus: AriGraph commits SPO
183	    /// knowledge → `triplets_to_palette_layers` produces fresh `[[u64; 64]; 8]`
184	    /// → this method swaps them into the live driver under a write lock.
185	    /// The next `dispatch()` call will see the new topology.
186	    #[inline]
187	    pub fn update_planes(&self, new_planes: [[u64; 64]; 8]) {
188	        let mut guard = self.planes.write().expect("planes RwLock poisoned");
189	        **guard = new_planes;
190	    }
191	
192	    /// Select the dispatch read substrate (W3 read-shim).
193	    ///
194	    /// Default (`mailbox-thoughtspace` OFF): the live singleton `BindSpace` —
195	    /// byte-identical to the pre-shim reads. Under the feature: the single
196	    /// designated `MailboxSoA` ([`DEFAULT_MAILBOX`]). `run()` keeps ONE body
197	    /// written against [`BackingStore`]; this method (NOT a `#[cfg]` inside
198	    /// `run`) selects which variant is constructed.
199	    #[inline]
200	    fn backing(&self) -> BackingStore<'_> {
201	        #[cfg(feature = "mailbox-thoughtspace")]
202	        {
203	            // OQ-D: multi-mailbox routing is W5. Until then AT MOST one mailbox
204	            // is the BindSpace surrogate; a singleton-shaped dispatch selects it.
205	            // An unmigrated driver (zero mailboxes) falls back to the singleton,
206	            // so the feature build never panics on a driver that hasn't been
207	            // populated with the designated mailbox yet.
208	            debug_assert!(
209	                self.mailboxes.len() <= 1,
210	                "mailbox-thoughtspace expects at most one designated mailbox \
211	                 (DEFAULT_MAILBOX) until W5 multi-mailbox routing; got {}",
212	                self.mailboxes.len()
213	            );
214	            if let Some(mb) = self.mailboxes.get(&DEFAULT_MAILBOX) {
215	                return BackingStore::Mailbox(mb);
216	            }
217	            BackingStore::Singleton(&self.bindspace)
218	        }
219	        #[cfg(not(feature = "mailbox-thoughtspace"))]
220	        {
221	            BackingStore::Singleton(&self.bindspace)
222	        }
223	    }
224	
225	    /// Run one dispatch, feeding a sink. This is the single hot path.
226	    fn run<S: ShaderSink>(&self, req: &ShaderDispatch, sink: &mut S) -> ShaderCrystal {
227	        // W3 read-shim: select the substrate (singleton BindSpace by default;
228	        // the designated MailboxSoA under `mailbox-thoughtspace`). The body
229	        // below is written ONCE against `backing` — no `#[cfg]` branches here.
230	        let backing = self.backing();
231	
232	        // ── Rung ascent loop (D-TRI-6) ──────────────────────────────────────
233	        // The persistent per-driver RungElevator's CURRENT level — advanced by
234	        // the PREVIOUS cycle's gate via `on_gate` at the end of this fn — selects
235	        // THIS cycle's cascade plane breadth. A dispatch whose requested base
236	        // rung differs from the elevator's tracked base resets the elevator
237	        // first, so streaks never leak across unrelated dispatch bases. At base
238	        // the mask is unchanged (no regression); above base it widens by union
239	        // (see `rung_widened_layer_mask` + its HAZARD(a) note).
240	        let effective_layer_mask = {
241	            let mut elevator = self
242	                .rung_elevator
243	                .write()
244	                .expect("rung_elevator RwLock poisoned");
245	            if elevator.base != req.rung {
246	                *elevator = RungElevator::new(req.rung);
247	            }
248	            rung_widened_layer_mask(elevator.base, elevator.level, req.layer_mask)
249	        };
250	
251	        // [1] Cheap meta prefilter (u32 column sweep).
252	        let passed_rows = backing.prefilter(req.rows, &req.meta_prefilter);
253	
254	        // [2] Resolve style — Auto reads the qualia of the FIRST surviving row.
255	        // D-CSV-5b: qualia is QualiaI4_16D; the shim converts to f32 at the read.
256	        let qualia_f32_arr: [f32; 17] = if let Some(&row) = passed_rows.first() {
257	            backing.qualia_17d(row as usize)
258	        } else {
259	            [0.0f32; 17]
260	        };
261	        let style_ord = auto_style::resolve(req.style, &qualia_f32_arr[..]);
262	
263	        // [3] Shader cascade — bgz17 O(1) per probed block.
264	        // Snapshot the planes under the read lock so the cascade sees a
265	        // consistent topology even if `update_planes` fires mid-dispatch.
266	        let planes_snapshot: [[u64; 64]; 8] = **self.planes.read().expect("planes RwLock poisoned");
267	        let shader = CognitiveShader::new(planes_snapshot, &self.semiring);
268	        let max_dist = (self.semiring.k as f32) * (self.semiring.k as f32);
269	        let mut hits = Vec::<ShaderHit>::with_capacity(passed_rows.len().min(64));
270	
271	        // TD-INT-10: optional NARS truth-table lookups per hit.
272	        let nars_tables = self.nars_tables.as_deref();
273	
274	        // Content-plane Hamming pre-pass (PR #259).
275	        const CONTENT_MATCH_PREDICATE: u8 = 0x01;
276	        const MAX_CONTENT_PREPASS_ROWS: usize = 256;
277	        const FP_BITS: f32 = (WORDS_PER_FP * 64) as f32;
278	        if passed_rows.len() <= MAX_CONTENT_PREPASS_ROWS {
279	            let style_cfg = &crate::engine_bridge::UNIFIED_STYLES[(style_ord % 12) as usize];
280	            let min_resonance = style_cfg.resonance_threshold;
281	
282	            for (i, &row_i) in passed_rows.iter().enumerate() {
283	                let fp_i = backing.content_row(row_i as usize);
284	                for (j_off, &row_j) in passed_rows.iter().enumerate().skip(i + 1) {
285	                    let fp_j = backing.content_row(row_j as usize);
286	                    let fp_i_bytes = unsafe {
287	                        std::slice::from_raw_parts(fp_i.as_ptr() as *const u8, WORDS_PER_FP * 8)
288	                    };
289	                    let fp_j_bytes = unsafe {
290	                        std::slice::from_raw_parts(fp_j.as_ptr() as *const u8, WORDS_PER_FP * 8)
291	                    };
292	                    let hamming =
293	                        ndarray::hpc::bitwise::hamming_distance_raw(fp_i_bytes, fp_j_bytes) as u32;
294	                    let resonance = 1.0 - (hamming as f32 / FP_BITS);
295	                    if resonance >= min_resonance {
296	                        hits.push(ShaderHit {
297	                            row: row_i,
298	                            distance: hamming.min(u16::MAX as u32) as u16,
299	                            predicates: CONTENT_MATCH_PREDICATE,
300	                            _pad: 0,

300	                            _pad: 0,
301	                            resonance,
302	                            cycle_index: i as u32,
303	                        });
304	                        hits.push(ShaderHit {
305	                            row: row_j,
306	                            distance: hamming.min(u16::MAX as u32) as u16,
307	                            predicates: CONTENT_MATCH_PREDICATE,
308	                            _pad: 0,
309	                            resonance,
310	                            cycle_index: j_off as u32,
311	                        });
312	                    }
313	                }
314	            }
315	        }
316	
317	        for (cycle_idx, &row) in passed_rows.iter().enumerate() {
318	            if cycle_idx as u16 >= req.max_cycles.saturating_mul(4) {
319	                break;
320	            }
321	            // Use the SPO `s_idx` of the row's edge as the query palette index.
322	            // Rows with edge=0 default to palette 0 (identity probe).
323	            let edge = backing.edge(row as usize);
324	            let query = edge.s_idx();
325	            let raw = shader.cascade(query, req.radius, effective_layer_mask);
326	            for hit in raw.into_iter().take(4) {
327	                let resonance = 1.0 / (1.0 + (hit.distance as f32 / max_dist));
328	
329	                // TD-INT-10: NARS truth lookup against precomputed tables.
330	                // The row's edge already carries a (frequency, confidence)
331	                // pair; we revise it against a hit-derived surrogate truth
332	                // (resonance as frequency, conservative half-confidence).
333	                // The result is currently observed only — see comment above.
334	                if let Some(tables) = nars_tables {
335	                    let f1 = edge.frequency_u8();
336	                    let c1 = edge.confidence_u8();
337	                    let f2 = (resonance.clamp(0.0, 1.0) * 255.0) as u8;
338	                    let c2 = 128u8;
339	                    let packed = tables.revise(f1, c1, f2, c2);
340	                    let _revised_truth = (unpack_f(packed), unpack_c(packed));
341	                }
342	
343	                hits.push(ShaderHit {
344	                    row,
345	                    distance: hit.distance,
346	                    predicates: hit.predicates,
347	                    _pad: 0,
348	                    resonance,
349	                    cycle_index: cycle_idx as u32,
350	                });
351	            }
352	        }
353	
354	        // Sort by resonance descending, keep top-8.
355	        hits.sort_by(|a, b| {
356	            b.resonance
357	                .partial_cmp(&a.resonance)
358	                .unwrap_or(std::cmp::Ordering::Equal)
359	        });
360	        hits.truncate(8);
361	
362	        // [4] Build the cycle_fingerprint with positional Markov braiding.
363	        //     Each row is rotated by its cycle_index before XOR — preserves
364	        //     position information structurally (binary-space vsa_permute analogue).
365	        //     Per I-SUBSTRATE-MARKOV: this activates the Markov ±5 property
366	        //     even in binary space; full f32 VSA bundle is the next step.
367	        let mut cycle_fp = [0u64; WORDS_PER_FP];
368	        for h in &hits {
