681	/// Combine the dispatch's 8-bit predicate-plane mask with the CURRENT rung.
682	/// At (or below) the dispatched base rung this returns `req_mask` UNCHANGED —
683	/// zero behaviour change for a thought sitting at its requested depth. Above
684	/// base, each Pearl level the rung has climbed UNIONs in additional predicate
685	/// planes, so the consulted set is a strict SUPERSET of `req_mask`: elevation
686	/// only ever WIDENS the cascade, never narrows it.
687	///
688	/// HAZARD (a) — axis translation (CORRECTNESS GATE). The p64
689	/// `CognitiveShader::cascade` `layer_mask` is an 8-bit PREDICATE-PLANE mask
690	/// (CAUSES..BECOMES; bit `z` gates plane `z`), NOT the 3-bit SPO projection
691	/// mask `RungLevel::causal_mask_bits()` returns. Feeding `causal_mask_bits()`
692	/// raw would be a category error AND, at base Surface (0b001), would collapse
693	/// the cascade to plane 0 only — a severe regression. So the rung's *Pearl
694	/// level* selects a predicate-plane widen-set, mirroring the Pearl→predicate
695	/// routing already in `p64_bridge::edge_to_layer_mask`. Because the widen is a
696	/// UNION, a caller that already asked for all planes (`0xFF`, the
697	/// `ShaderDispatch` default) sees no change — you cannot consult more than every
698	/// plane. The specific planes each Pearl level unlocks are a calibration a later
699	/// probe may retune; the identity-at-base and superset-monotone properties are
700	/// invariant.
701	fn rung_widened_layer_mask(base: RungLevel, level: RungLevel, req_mask: u8) -> u8 {
702	    if (level as u8) <= (base as u8) {
703	        return req_mask;
704	    }
705	    // p64 predicate-plane bit positions (mirror p64_bridge::{CAUSES..BECOMES}):
706	    // CAUSES=0 ENABLES=1 SUPPORTS=2 CONTRADICTS=3 REFINES=4 ABSTRACTS=5
707	    // GROUNDS=6 BECOMES=7.
708	    const ENABLES: u8 = 1 << 1;
709	    const CONTRADICTS: u8 = 1 << 3;
710	    const REFINES: u8 = 1 << 4;
711	    const ABSTRACTS: u8 = 1 << 5;
712	    const BECOMES: u8 = 1 << 7;
713	    // Pearl-level → predicate widen-set (superset-monotone):
714	    //   L1 observation    → nothing beyond req_mask,
715	    //   L2 intervention   → +ENABLES +REFINES,
716	    //   L3 counterfactual → also +CONTRADICTS +ABSTRACTS +BECOMES.
717	    let widen = match level.pearl_level() {
718	        1 => 0,
719	        2 => ENABLES | REFINES,
720	        _ => ENABLES | REFINES | CONTRADICTS | ABSTRACTS | BECOMES,
721	    };
722	    req_mask | widen
723	}
